def Strongest_Extension(class_name, extensions):
    def count_distinct_characters(string: str) -> int:
        lower_string = string.lower()
        distinct_characters = set(lower_string)
        return len(distinct_characters)

    # Initialize the strongest extension as the first in the list
    strong = extensions[0]

    # Calculate the strength of the first extension
    my_val = len([x for x in extensions[0] if x.isalpha() and x.isupper()]) - len([x for x in extensions[0] if x.isalpha() and x.islower()])

    # Iterate through each extension in the list
    for s in extensions:
        # Calculate the strength of the current extension
        val = len([x for x in s if x.isalpha() and x.isupper()]) - len([x for x in s if x.isalpha() and x.islower()])

        # Update the strongest extension if the current extension has higher strength
        if val > my_val:
            strong = s
            my_val = val

    # Return the count of distinct characters in the strongest extension
    return count_distinct_characters(strong)

