def histogram(test: str) -> dict:
    # :param test: str - A string of space-separated words.
#     :return: dict - A dictionary containing the most frequent word (the first one in case of a tie) and its frequency. Returns an empty dictionary if the input string is empty.
#     Examples:
#     >>> histogram('a b c a b')
#     {'a': 2}
#     >>> histogram('')
#     {}
#     >>> histogram('b b b b a')
#     {'b': 4}
#     >>> histogram('r t g')
#     {'r': 1}
#     >>> histogram('a b c')
#     {'a': 1}
#     >>> histogram('a')
#     {'a': 1}
#     >>> histogram('a b b a')
#     {'a': 2}
#     >>> histogram('a b c d g')
#     {'a': 1}

        if not test:
            return {}

        words = test.split()

        # Use a dictionary to store word counts
        word_counts = {}
        for word in words:
            if word in word_counts:
                word_counts[word] += 1
            else:
                word_counts[word] = 1

        max_frequency = 0
        most_frequent_word = ''

        # Iterate through the words in their original order to handle ties
        # The first word encountered with the max frequency should be chosen
        # Initialize with the first word's frequency and the first word itself
        if words: # This check is redundant due to 'if not test' above, but harmless
            most_frequent_word = words[0]
            max_frequency = word_counts[words[0]]

        # Now, iterate through the unique words (keys of word_counts)
        # or better, iterate through the original list of words to maintain order for ties
        for word in words:
            current_frequency = word_counts[word]
            if current_frequency > max_frequency:
                max_frequency = current_frequency
                most_frequent_word = word

        return {most_frequent_word: max_frequency}


