def x_or_y(n, x, y):
    """A modified program which returns the length of x's string if n is prime, else returns the number of vowels in y's string."""

    # Optimized prime check up to sqrt(n)
    if n < 2:
        return len(str(y))

    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            break
    else:
        # n is prime
        return len(str(x))

    # n is not prime
    # Count vowels in y's string
    vowels = 'aeiouAEIOU'
    count = 0
    for char in str(y):
        if char in vowels:
            count += 1
    return count

