def modified_prime_fib(n: int):
    import math

    def is_prime(p: int) -> bool:
        if p < 2:
            return False
        for k in range(2, min(int(math.sqrt(p)) + 1, p - 1)):
            if p % k == 0:
                return False
        return True

    f = [0, 1]
    while True:
        f.append(f[-1] + f[-2])
        if is_prime(f[-1]):
            n -= 1
        if n == 0:
            fib_prime = f[-1]
            break

    digits = list(str(fib_prime))
    evens = [digits[i] for i in range(0, len(digits), 2)]
    evens.sort()
    sum_evens = sum(int(d) for d in evens)
    return sum_evens

