def filter_integers(values: List[Any]) -> List[int]:
    note_map = {'o': 4, 'o|': 2, '.|': 1}
    result = []
    for x in values:
        if isinstance(x, int):
            result.append(x ** 2)  # Square the integer value
        elif isinstance(x, str) and x in note_map:
            result.append(note_map[x])
    return result

