def check_dict_case(dict):
    """
    Given a dictionary, return a list of coordinates (row, column) of keys if all keys are strings in lower 
    case or all keys are strings in upper case. Otherwise, return False. The function should return False is the given dictionary is empty.
    """
    if not dict:
        return False

    state = "start"
    for key in dict.keys():
        if not isinstance(key, str):
            state = "mixed"
            break
        if state == "start":
            if key.isupper():
                state = "upper"
            elif key.islower():
                state = "lower"
            else:
                break
        elif (state == "upper" and not key.isupper()) or (state == "lower" and not key.islower()):
            state = "mixed"
            break
        else:
            break

    if state not in ["upper", "lower"]:
        return False

    coords = []
    for i, key in enumerate(dict.keys()):
        coords.append((i, 0))  # column is 0 for all keys

    # Sort by row ascending, then column descending (but column is 0)
    coords.sort(key=lambda x: (x[0], -x[1]))
    return coords

