#     {'number': 123.456, 'integer_part': 123, 'decimal_part': 0.45600000000000307, 'digit_frequency': {'4': 1, '5': 1, '6': 1, '0': 11, '3': 1}}
#     >>> truncate_number(3.5)
#     {'number': 3.5, 'integer_part': 3, 'decimal_part': 0.5, 'digit_frequency': {'5': 1}}

        integer_part = int(number)
        decimal_part = number - integer_part
        decimal_part_str = "{:.32f}".format(decimal_part)
