    # Input is a space-delimited string of numerals from 'zero' to 'nine'.
#     Valid choices are 'zero', 'one', 'two', 'three', 'four', 'five', 'six', 'seven', 'eight' and 'nine'.
#     Return a dictionary with:
#     - 'sorted' key containing the string with numbers sorted from smallest to largest
#     - 'grades' key containing letter grades for each number's value (treating the numeric value as GPA)
#     :param numbers: str - Space-separated string of number words from 'zero' to 'nine'
#     :return: dict - Dictionary with 'sorted' (str) and 'grades' (list) keys
#     Examples:
#     >>> sort_numbers('six five four three two one zero')
#     {'sorted': 'zero one two three four five six', 'grades': ['E', 'D', 'C', 'B', 'A+', 'A', 'A']}
#     >>> sort_numbers('five zero four seven nine eight')
#     {'sorted': 'zero four five seven eight nine', 'grades': ['E', 'A+', 'A', 'A', 'A', 'A']}
#     >>> sort_numbers('')
#     {'sorted': '', 'grades': []}
#     >>> sort_numbers('three one five')
#     {'sorted': 'one three five', 'grades': ['D', 'B', 'A']}
#     >>> sort_numbers('three five nine')
#     {'sorted': 'three five nine', 'grades': ['B', 'A', 'A']}
#     >>> sort_numbers('three')
#     {'sorted': 'three', 'grades': ['B']}

        if not numbers.strip():
            return {'sorted': '', 'grades': []}
        mapping = {
            'zero': 0,
            'one': 1,
            'two': 2,
            'three': 3,
            'four': 4,
            'five': 5,
            'six': 6,
            'seven': 7,
            'eight': 8,
            'nine': 9
        }
        reverse_mapping = {v: k for k, v in mapping.items()}
        numeric_list = [mapping[n] for n in numbers.split()] if numbers.split() else []
