def strlen(string: str) -> dict:
    """Return advanced string analysis including length, balanced parentheses check,
    and character frequency for both the string and its reverse.
    >>> strlen('')
    {'length': 0, 'balanced': True, 'char_freq': {}, 'reverse_balanced': True, 'reverse_char_freq': {}}
    >>> strlen('abc')
    {'length': 3, 'balanced': False, 'char_freq': {'a': 1, 'b': 1, 'c': 1}, 'reverse_balanced': False, 'reverse_char_freq': {'c': 1, 'b': 1, 'a': 1}}
    >>> strlen('(())')
    {'length': 4, 'balanced': True, 'char_freq': {'(': 2, ')': 2}, 'reverse_balanced': True, 'reverse_char_freq': {')': 2, '(': 2}}
    """

    def is_balanced(s):
        balance = 0
        for char in s:
            if char == '(':
                balance += 1
            elif char == ')':
                balance -= 1
                if balance < 0:
                    return False
        return balance == 0

    def char_frequency(s):
        freq = {}
        for char in s:
            freq[char] = freq.get(char, 0) + 1
        return freq

    reverse_str = string[::-1]

    result = {
        'length': len(string),
        'balanced': is_balanced(string),
        'char_freq': char_frequency(string),
        'reverse_balanced': is_balanced(reverse_str),
        'reverse_char_freq': char_frequency(reverse_str)
    }

    return result

