def largest_divisor(n: int) -> str:
    """For a given number n, find the largest number that divides n evenly, smaller than n,
    and return its corresponding letter grade based on the divisor's value.
    The grading scale is:
        4.0: A+, >3.7: A, >3.3: A-, >3.0: B+, >2.7: B, >2.3: B-, 
        >2.0: C+, >1.7: C, >1.3: C-, >1.0: D+, >0.7: D, >0.0: D-, 0.0: E
    >>> largest_divisor(15)
    'B'
    """

    # Find the largest divisor
    divisor = None
    for i in reversed(range(n)):
        if n % i == 0:
            divisor = i
            break

    # Convert divisor to GPA (scaled down for grading)
    gpa = divisor / (n / 4.0) if n != 0 else 0.0

    # Determine letter grade
    if gpa == 4.0:
        return "A+"
    elif gpa > 3.7:
        return "A"
    elif gpa > 3.3:
        return "A-"
    elif gpa > 3.0:
        return "B+"
    elif gpa > 2.7:
        return "B"
    elif gpa > 2.3:
        return "B-"
    elif gpa > 2.0:
        return "C+"
    elif gpa > 1.7:
        return "C"
    elif gpa > 1.3:
        return "C-"
    elif gpa > 1.0:
        return "D+"
    elif gpa > 0.7:
        return "D"
    elif gpa > 0.0:
        return "D-"
    else:
        return "E"

