def max_element(l: list):
    """Return a dictionary containing the max element and corresponding letter grade.
    with additional statistical information.
    >>> max_element([1, 2, 3])
    {'max_value': 3, 'letter_grade': 'A-', 'min_value': 1, 'range': 2}
    >>> max_element([5, 3, -5, 2, -3, 3, 9, 0, 123, 1, -10])
    {'max_value': 123, 'letter_grade': 'A+', 'min_value': -10, 'range': 133}
    """
    # Calculate max value (original functionality)
    max_val = l[0]
    min_val = l[0]
    for e in l:
        if e > max_val:
            max_val = e
        if e < min_val:
            min_val = e

    # Convert max value to GPA scale (0-4) for grading
    normalized_gpa = min(4.0, max(0.0, max_val / 30))  # Scale factor of 30

    # Determine letter grade (from second problem)
    if normalized_gpa == 4.0:
        letter = "A+"
    elif normalized_gpa > 3.7:
        letter = "A"
    elif normalized_gpa > 3.3:
        letter = "A-"
    elif normalized_gpa > 3.0:
        letter = "B+"
    elif normalized_gpa > 2.7:
        letter = "B"
    elif normalized_gpa > 2.3:
        letter = "B-"
    elif normalized_gpa > 2.0:
        letter = "C+"
    elif normalized_gpa > 1.7:
        letter = "C"
    elif normalized_gpa > 1.3:
        letter = "C-"
    elif normalized_gpa > 1.0:
        letter = "D+"
    elif normalized_gpa > 0.7:
        letter = "D"
    elif normalized_gpa > 0.0:
        letter = "D-"
    else:
        letter = "E"

    return {
        'max_value': max_val,
        'letter_grade': letter,
        'min_value': min_val,
        'range': max_val - min_val
    }

